html:
{% set company_name = frappe.db.get_value("Company", doc.company, "company_name") %}
{% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
{% set company_phone_no = frappe.db.get_value("Company", doc.company, "phone_no") %}
{% set company_email = frappe.db.get_value("Company", doc.company, "email") %}
{% set company_website = frappe.db.get_value("Company", doc.company, "website") %}
{% set company_pin = frappe.db.get_value("Company", doc.company, "tax_id") %}

{% set address_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = frappe.db.get_value("Address", address_name, ["address_line1", "address_line2", "city", "pincode", "country"], as_dict=True) %}

<style>
    @media print {
        .doctype-heading {
            background-color: #2c3e50 !important;
            color: #fff !important;
            -webkit-print-color-adjust: exact;
        }
    }
    /* Rounded corners for all bordered containers */
    .receipt-box, table, .bordered {
        border-radius: 8px;
        overflow: hidden;
    }
    table {
        border-collapse: separate;
        border-spacing: 0;
    }
    th, td {
        padding: 8px;
    }
    .amount-box {
        background-color: #f8f9fa;
        border-radius: 8px;
        padding: 12px;
        margin: 10px 0;
        font-size: 14px;
    }
    .total-row {
        background-color: #e9ecef;
        font-weight: bold;
    }
</style>

<div id="header-html" style="margin: 20px auto; width: 98%; padding: 15px; border: 2px solid #2c3e50; border-radius: 12px; background-color: #f9f9f9; box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1);">
    <div style="display: flex; align-items: center;">
        <!-- Logo and Company Details -->
        <div style="flex: 1; display: flex; align-items: flex-start;">
            {% if company_logo %}
                <img src="{{ company_logo }}" alt="Company Logo" style="max-width: 100px; max-height: 120px; height: auto; margin-right: 20px; border: 1px solid #ccc; padding: 5px; border-radius: 8px;">
            {% else %}
                <img src="/files/default_logo.jpeg" alt="Default Company Logo" style="max-width: 100px; max-height: 120px; height: auto; margin-right: 20px; border: 1px solid #ccc; padding: 5px; border-radius: 8px;">
            {% endif %}
            <div style="font-size: 12px; line-height: 1.6; color: #333;">
                <strong style="font-size: 14px; color: #000;">{{ company_name }}</strong><br>
                {% if company_address %}
                    {{ company_address.address_line1 }}{% if company_address.pincode %}, {{ company_address.pincode }}{% endif %}<br>
                    {% if company_address.address_line2 %}
                        {{ company_address.address_line2 }},<br>
                    {% endif %}
                    {{ company_address.city }},
                    {{ company_address.country }}.<br>
                {% endif %}
                {% if company_phone_no %}
                    Phone: {{ company_phone_no }}<br>
                {% endif %}
                {% if company_email %}
                    Email: {{ company_email }}<br>
                {% endif %}
                {% if company_website %}
                    Website: <a href="http://{{ company_website }}" style="color: #0056b3; text-decoration: none;">{{ company_website }}</a>
                {% endif %}
            </div>
        </div>

        <!-- Invoice Heading and Number -->
        <div style="flex: 0.8; text-align: right;">
            <div class="doctype-heading" style="display: inline-block; text-align: center; font-size: 16px; font-weight: bold; padding: 8px 20px; border-radius: 20px; background-color: #2c3e50; color: #fff;">
                PURCHASE INVOICE
            </div>
            <table style="width: 100%; margin-top: 10px; font-size: 11px; border: none;">
                <tr>
                    <td style="text-align: right; padding: 2px;">Posting Date:</td>
                    <td style="text-align: right; padding: 2px;">{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</td>
                </tr>
                <tr>
                    <td style="text-align: right; padding: 2px;">Invoice No:</td>
                    <td style="text-align: right; padding: 2px;"><b>{{ doc.name }}</b></td>
                </tr>
                <tr>
                    <td style="text-align: right; padding: 2px;">Due Date:</td>
                    <td style="text-align: right; padding: 2px;">{{ frappe.utils.formatdate(doc.due_date, "dd-MM-yyyy") if doc.due_date else '' }}</td>
                </tr>
            </table>
        </div>
    </div>
</div>

<!-- Main Invoice Body -->
<div style="width: 98%; margin: 20px auto; border: 1px solid #2c3e50; border-radius: 12px; padding: 20px; background-color: #ffffff;">

    <!-- Supplier Details -->
    <div style="font-size: 14px; margin-bottom: 20px;">
        <strong>FROM (SUPPLIER)</strong><br>
        <span style="font-size: 18px;">{{ doc.supplier_name or doc.supplier }}</span><br>
        {% set supplier_address = frappe.db.get_value("Dynamic Link", {"link_doctype": "Supplier", "link_name": doc.supplier, "parenttype": "Address"}, "parent") %}
        {% if supplier_address %}
            {{ frappe.db.get_value("Address", supplier_address, "display") }}
        {% endif %}
    </div>

    <!-- Invoice Summary Box -->
    <div class="amount-box" style="background-color: #f0f8ff; border: 1px solid #2c3e50; border-radius: 10px; margin-bottom: 15px;">
        <table style="width: 100%; font-size: 13px; border: none;">
            <tr>
                <td><strong>Supplier Invoice No:</strong> {{ doc.bill_no or '' }}</td>
                <td><strong>Bill Date:</strong> {{ frappe.utils.formatdate(doc.bill_date, "dd-MM-yyyy") if doc.bill_date else '' }}</td>
                <td><strong>Project:</strong> {{ doc.project or '' }}</td>
            </tr>
            <tr>
                <td><strong>Purchase Order:</strong> 
                    {% if doc.items and doc.items[0].purchase_order %}
                        {{ doc.items[0].purchase_order }}
                    {% endif %}
                </td>
                <td><strong>Status:</strong> {{ doc.status }}</td>
                <td></td>
            </tr>
        </table>
    </div>

    <!-- Items Table -->
    <table style="width: 100%; font-size: 11px; border: 1px solid #2c3e50; border-radius: 8px; margin-top: 15px;">
        <thead>
            <tr style="background-color: #e9ecef;">
                <th style="width: 5%; text-align: center;">#</th>
                <th style="width: 20%;">Item Code</th>
                <th style="width: 35%;">Description</th>
                <th style="width: 8%; text-align: center;">Qty</th>
                <th style="width: 8%; text-align: center;">UOM</th>
                <th style="width: 12%; text-align: right;">Rate</th>
                <th style="width: 12%; text-align: right;">Amount</th>
            </tr>
        </thead>
        <tbody>
            {% set total_qty = 0 %}
            {% set total_amount = 0 %}
            {% for row in doc.items %}
            <tr>
                <td style="text-align: center;">{{ row.idx }}</td>
                <td>{{ row.item_code }}</td>
                <td>{{ row.item_name }}</td>
                <td style="text-align: center;">{{ row.qty }}</td>
                <td style="text-align: center;">{{ row.uom }}</td>
                <td style="text-align: right;">{{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}</td>
                <td style="text-align: right;">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
            </tr>
            {% set total_qty = total_qty + row.qty %}
            {% set total_amount = total_amount + row.amount %}
            {% endfor %}
        </tbody>
        <tfoot>
            <tr class="total-row">
                <th colspan="3" style="text-align: right;">Totals:</th>
                <th style="text-align: center;">{{ total_qty }}</th>
                <th></th>
                <th></th>
                <th style="text-align: right;">{{ frappe.utils.fmt_money(total_amount, currency=doc.currency) }}</th>
            </tr>
        </tfoot>
    </table>

    <!-- Tax and Grand Total Section -->
    {% if doc.taxes %}
    <table style="width: 100%; font-size: 11px; margin-top: 10px; border: none;">
        {% for tax in doc.taxes %}
        <tr>
            <td style="text-align: right; width: 80%;">{{ tax.description }}:</td>
            <td style="text-align: right; width: 20%;">{{ frappe.utils.fmt_money(tax.tax_amount, currency=doc.currency) }}</td>
        </tr>
        {% endfor %}
        <tr style="font-weight: bold; font-size: 13px;">
            <td style="text-align: right;">Grand Total:</td>
            <td style="text-align: right;">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td>
        </tr>
    </table>
    {% else %}
    <div style="margin-top: 10px; text-align: right; font-weight: bold; font-size: 13px;">
        Grand Total: {{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}
    </div>
    {% endif %}

    <!-- Amount in Words -->
    <div style="margin-top: 10px; text-align: right; font-size: 12px; color: #555;">
        {{ doc.in_words or '' }}
    </div>

    <!-- Outstanding Amount (if any) -->
    {% if doc.outstanding_amount != 0 %}
    <div style="margin-top: 10px; text-align: right; font-size: 12px; font-weight: bold; color: #dc3545;">
        Outstanding Amount: {{ frappe.utils.fmt_money(doc.outstanding_amount, currency=doc.currency) }}
    </div>
    {% endif %}

    <!-- Terms and Conditions -->
    {% if doc.terms %}
    <div style="margin-top: 20px; padding: 10px; border: 1px dashed #aaa; border-radius: 8px; font-size: 11px;">
        <strong>Terms & Conditions:</strong><br>
        {{ doc.terms }}
    </div>
    {% endif %}

    <!-- Signature Lines -->
    <!--<div style="margin-top: 30px; display: flex; justify-content: space-between;">-->
    <!--    <div style="width: 45%;">-->
    <!--        <div style="border-top: 1px solid #000; width: 80%; margin-bottom: 5px;"></div>-->
    <!--        <strong>Authorized Signatory</strong>-->
    <!--    </div>-->
    <!--    <div style="width: 45%; text-align: right;">-->
    <!--        <div style="border-top: 1px solid #000; width: 80%; margin-left: 20%; margin-bottom: 5px;"></div>-->
    <!--        <strong>Supplier's Signature</strong>-->
    <!--    </div>-->
    <!--</div>-->

    <!-- Created By / On and Status -->
    <div style="margin-top: 20px; font-size: 10px; color: #777; border-top: 1px solid #eee; padding-top: 10px;">
        <span>Created by: {{ doc.owner }} on {{ doc.get_formatted('creation') }}</span>
        {% if doc.docstatus == 1 %}
        <span style="float: right;">Submitted</span>
        {% elif doc.docstatus == 0 %}
        <span style="float: right; color: #ff9800;">DRAFT</span>
        {% else %}
        <span style="float: right; color: #dc3545;">CANCELLED</span>
        {% endif %}
    </div>
</div>

<!-- Duplicate / Times Printed Handling -->
{% set times_printed = doc.times_printed or 0 %}
{% if times_printed >= 1 %}
    <div style="text-align: center; font-size: 14px; font-weight: bold; color: #dc3545; margin: 10px 0;">DUPLICATE</div>
{% endif %}

<!-- Letterhead Footer (if any) -->
{% set footer = frappe.db.get_value("Letter Head", doc.letter_head, "footer") %}
{% if footer %}
    <div id="footer-html" class="visible-pdf visible-print text-center" style="font-size:10px">
        <div class="letter-head-footer text-size-10 text-center" style="font-size: 10px;">
            {{ footer }}
        </div>
    </div>
{% endif %}

<!-- Bottom fixed footer (optional) -->
<div style="position: fixed; bottom: 0; left: 0; width: 100%; text-align: center; padding: 10px 0; font-size: 10px; color: #666; background-color: #ffffff; border-top: 1px solid #e9ecef; border-radius: 8px 8px 0 0;">
    This is a computer generated invoice – valid with authorized signature.
</div>
